{
  "title": "数据窃取",
  "scene": "你站在废弃的赛博朋克都市中，眼前是一个闪着蓝光的服务器机房。门口的大门上贴着“安全级别：高”的标签。机房内部安装着复杂的摄像头和传感器，但似乎已经被破坏过。你悄悄绕过大门，进入机房内部。",
  "goal": "偷取服务器中的重要数据。",
  "choices": [
    {
      "id": "A",
      "text": "尝试找到备用控制台，启动窃取数据的程序。",
      "outcome": "成功启动了程序，但引起了监控摄像头的注意，导致警报响起。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "寻找服务器旁边的隐藏通风口，使用工具攀爬进入。",
      "outcome": "顺利进入通风口，抵达服务器上方，快速下载所需数据。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "用随身携带的病毒攻击服务器，试图直接获取数据。",
      "outcome": "病毒启动，服务器被成功入侵，但病毒也触发了自毁程序，服务器开始爆炸。",
      "result": "fail",
      "next": "bad_end"
    }
  ]
}
